-- =====================================================================
-- A&E Wearable Patient Monitoring System - Oracle SQL
-- Simulated shift: 24 Oct 2026, 06:30-12:00, 14 patients
-- All data is FICTIONAL. NHS numbers use the 999 test range.
-- =====================================================================

DROP VIEW v_open_alerts;
DROP VIEW v_latest_vitals;
DROP VIEW v_current_patients;
DROP TABLE audit_log CASCADE CONSTRAINTS;
DROP TABLE alert CASCADE CONSTRAINTS;
DROP TABLE alert_threshold CASCADE CONSTRAINTS;
DROP TABLE risk_score CASCADE CONSTRAINTS;
DROP TABLE manual_observation CASCADE CONSTRAINTS;
DROP TABLE vital_reading CASCADE CONSTRAINTS;
DROP TABLE device_assignment CASCADE CONSTRAINTS;
DROP TABLE wristband CASCADE CONSTRAINTS;
DROP TABLE patient CASCADE CONSTRAINTS;
DROP TABLE staff CASCADE CONSTRAINTS;
DROP TABLE triage_category CASCADE CONSTRAINTS;
DROP TABLE zone CASCADE CONSTRAINTS;
DROP TABLE role CASCADE CONSTRAINTS;

CREATE TABLE role(
    role_id NUMBER(3) PRIMARY KEY,
    role_name VARCHAR2(20) NOT NULL,
    description VARCHAR2(80) NOT NULL);

CREATE TABLE zone(
    zone_id NUMBER(3) PRIMARY KEY,
    zone_name VARCHAR2(30) NOT NULL,
    description VARCHAR2(100) NOT NULL,
    capacity NUMBER(3) NOT NULL);

CREATE TABLE triage_category(
    triage_id NUMBER(1) PRIMARY KEY,
    category_name VARCHAR2(15) NOT NULL,
    colour VARCHAR2(10) NOT NULL,
    colour_code VARCHAR2(7) NOT NULL,
    max_wait_mins NUMBER(3) NOT NULL);

CREATE TABLE staff(
    staff_id NUMBER(4) PRIMARY KEY,
    role_id NUMBER(3) REFERENCES role(role_id) NOT NULL,
    forename VARCHAR2(25) NOT NULL,
    surname VARCHAR2(25) NOT NULL,
    email VARCHAR2(50) UNIQUE NOT NULL,
    phone_number VARCHAR2(15) NOT NULL,
    password_hash VARCHAR2(64) NOT NULL,
    is_active CHAR(1) DEFAULT 'Y' CHECK (is_active IN ('Y','N')));

CREATE TABLE patient(
    patient_id NUMBER(5) PRIMARY KEY,
    nhs_number VARCHAR2(10) UNIQUE,
    forename VARCHAR2(25) NOT NULL,
    surname VARCHAR2(25) NOT NULL,
    dob DATE NOT NULL,
    sex CHAR(1) NOT NULL CHECK (sex IN ('M','F','U')),
    arrival_time TIMESTAMP NOT NULL,
    presenting_complaint VARCHAR2(100) NOT NULL,
    triage_id NUMBER(1) REFERENCES triage_category(triage_id) NOT NULL,
    zone_id NUMBER(3) REFERENCES zone(zone_id) NOT NULL,
    status VARCHAR2(15) NOT NULL CHECK (status IN ('Waiting','In Treatment','Admitted','Discharged')),
    departed_at TIMESTAMP);

CREATE TABLE wristband(
    device_id NUMBER(4) PRIMARY KEY,
    serial_number VARCHAR2(20) UNIQUE NOT NULL,
    firmware_version VARCHAR2(10) NOT NULL,
    battery_level NUMBER(3) NOT NULL CHECK (battery_level BETWEEN 0 AND 100),
    status VARCHAR2(15) NOT NULL CHECK (status IN ('Available','In Use','Charging','Faulty')),
    last_seen_at TIMESTAMP);

CREATE TABLE device_assignment(
    assignment_id NUMBER(5) PRIMARY KEY,
    patient_id NUMBER(5) REFERENCES patient(patient_id) NOT NULL,
    device_id NUMBER(4) REFERENCES wristband(device_id) NOT NULL,
    assigned_by NUMBER(4) REFERENCES staff(staff_id) NOT NULL,
    assigned_at TIMESTAMP NOT NULL,
    removed_at TIMESTAMP);

CREATE TABLE vital_reading(
    reading_id NUMBER(7) PRIMARY KEY,
    assignment_id NUMBER(5) REFERENCES device_assignment(assignment_id) NOT NULL,
    recorded_at TIMESTAMP NOT NULL,
    heart_rate NUMBER(3),
    spo2 NUMBER(3) CHECK (spo2 BETWEEN 0 AND 100),
    resp_rate NUMBER(2),
    skin_temp NUMBER(3,1),
    fall_detected CHAR(1) DEFAULT 'N' CHECK (fall_detected IN ('Y','N')));

CREATE INDEX idx_reading_assign_time ON vital_reading(assignment_id, recorded_at);

CREATE TABLE manual_observation(
    obs_id NUMBER(6) PRIMARY KEY,
    patient_id NUMBER(5) REFERENCES patient(patient_id) NOT NULL,
    staff_id NUMBER(4) REFERENCES staff(staff_id) NOT NULL,
    recorded_at TIMESTAMP NOT NULL,
    systolic_bp NUMBER(3) NOT NULL,
    diastolic_bp NUMBER(3) NOT NULL,
    temperature NUMBER(3,1) NOT NULL,
    consciousness CHAR(1) NOT NULL CHECK (consciousness IN ('A','C','V','P','U')),
    on_oxygen CHAR(1) DEFAULT 'N' CHECK (on_oxygen IN ('Y','N')),
    notes VARCHAR2(200));

CREATE TABLE risk_score(
    score_id NUMBER(6) PRIMARY KEY,
    patient_id NUMBER(5) REFERENCES patient(patient_id) NOT NULL,
    obs_id NUMBER(6) REFERENCES manual_observation(obs_id),
    reading_id NUMBER(7) REFERENCES vital_reading(reading_id),
    calculated_at TIMESTAMP NOT NULL,
    news2_total NUMBER(2) NOT NULL,
    risk_level VARCHAR2(10) NOT NULL CHECK (risk_level IN ('Low','Low-Medium','Medium','High')));

CREATE TABLE alert_threshold(
    threshold_id NUMBER(3) PRIMARY KEY,
    vital_name VARCHAR2(20) NOT NULL,
    min_value NUMBER(5,1),
    max_value NUMBER(5,1),
    severity VARCHAR2(10) NOT NULL CHECK (severity IN ('Low','Medium','High')),
    description VARCHAR2(100) NOT NULL);

CREATE TABLE alert(
    alert_id NUMBER(6) PRIMARY KEY,
    patient_id NUMBER(5) REFERENCES patient(patient_id) NOT NULL,
    reading_id NUMBER(7) REFERENCES vital_reading(reading_id),
    score_id NUMBER(6) REFERENCES risk_score(score_id),
    threshold_id NUMBER(3) REFERENCES alert_threshold(threshold_id),
    alert_type VARCHAR2(25) NOT NULL,
    severity VARCHAR2(10) NOT NULL CHECK (severity IN ('Low','Medium','High')),
    message VARCHAR2(150) NOT NULL,
    triggered_at TIMESTAMP NOT NULL,
    status VARCHAR2(15) NOT NULL CHECK (status IN ('Open','Acknowledged','Resolved')),
    acknowledged_by NUMBER(4) REFERENCES staff(staff_id),
    acknowledged_at TIMESTAMP,
    resolved_at TIMESTAMP);

CREATE TABLE audit_log(
    log_id NUMBER(7) PRIMARY KEY,
    staff_id NUMBER(4) REFERENCES staff(staff_id) NOT NULL,
    action VARCHAR2(30) NOT NULL,
    table_name VARCHAR2(30) NOT NULL,
    record_id NUMBER(7) NOT NULL,
    logged_at TIMESTAMP NOT NULL,
    details VARCHAR2(200));


