-- =====================================================================
-- Views for the website dashboard
-- =====================================================================

-- Patients still in the department with their active wristband
CREATE OR REPLACE VIEW v_current_patients AS
SELECT p.patient_id, p.forename, p.surname, p.nhs_number,
       FLOOR(MONTHS_BETWEEN(SYSDATE, p.dob) / 12) AS age,
       p.presenting_complaint, p.status, p.arrival_time,
       t.triage_id, t.category_name AS triage, t.colour_code,
       z.zone_name, da.assignment_id, da.device_id
FROM patient p
JOIN triage_category t ON t.triage_id = p.triage_id
JOIN zone z ON z.zone_id = p.zone_id
LEFT JOIN device_assignment da ON da.patient_id = p.patient_id AND da.removed_at IS NULL
WHERE p.status IN ('Waiting','In Treatment');

-- Most recent wristband reading for each active assignment
CREATE OR REPLACE VIEW v_latest_vitals AS
SELECT patient_id, assignment_id, recorded_at, heart_rate, spo2, resp_rate, skin_temp, fall_detected
FROM (
    SELECT da.patient_id, vr.*,
           ROW_NUMBER() OVER (PARTITION BY vr.assignment_id ORDER BY vr.recorded_at DESC) AS rn
    FROM vital_reading vr
    JOIN device_assignment da ON da.assignment_id = vr.assignment_id
    WHERE da.removed_at IS NULL)
WHERE rn = 1;

-- Alerts needing attention, most severe and oldest first
CREATE OR REPLACE VIEW v_open_alerts AS
SELECT a.alert_id, a.patient_id, p.forename || ' ' || p.surname AS patient_name,
       z.zone_name, a.alert_type, a.severity, a.message, a.triggered_at, a.status,
       s.forename || ' ' || s.surname AS acknowledged_by
FROM alert a
JOIN patient p ON p.patient_id = a.patient_id
JOIN zone z ON z.zone_id = p.zone_id
LEFT JOIN staff s ON s.staff_id = a.acknowledged_by
WHERE a.status IN ('Open','Acknowledged')
ORDER BY CASE a.severity WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END, a.triggered_at;

